-- EXECUTED 2026-11-11 (read-only). Post-check: live vs manifest, scratch schema gone, old backup intact, no Phase-1 tables in public, live structure == fingerprints.
select 'live_vs_manifest' k, count(*) filter (where (xpath('/row/c/text()', query_to_xml(format('select count(*) c from public.%I',m.tbl),false,true,'')))[1]::text::bigint = m.row_count) ok_rows, count(*) total from backup_phase1._manifest m union all select 'restore_test_schema_exists', count(*), 0 from pg_namespace where nspname='restore_test' union all select 'old_backup_20261110_tables', count(*), 0 from pg_class where relnamespace='backup_20261110'::regnamespace and relkind='r' union all select 'phase1_tables_in_public', count(*), 0 from pg_class where relnamespace='public'::regnamespace and relname in ('work_relationship','ref_relationship_type') union all select 'live_struct_matches', count(*) filter (where f.h=m.h and f.n=m.n), count(*) from backup_phase1._struct_manifest m join backup_phase1.fingerprint('public') f using(kind) union all select 'backup_phase1_objects', count(*), 0 from pg_class where relnamespace='backup_phase1'::regnamespace and relkind='r';
